// TH14 v1.00b stage 3 boss nonspell 1.
// source: st03bs.ecl.txt::Boss1 (lines 54-81), dependency st03bs.ecl.txt::Boss1_at (83-122).
// entry state (context_only st03bs.ecl.txt::Boss 8-52): position (0,128), hurt/hit box 48x48
// (circle radius 24), limit moveLimit(0,128,280,64) line 28. SPELL_ID practice jumps excluded.

const TH14_BALL2: int = 432;      // native type 5 (SHOOT_DATA sprite)
const TH14_BIG_BALL: int = 640;   // native type 18 (main ring)

const TIME_LIMIT: int = 2884;     // 120 opening + 2400 source timeout + 360 tail + 4
const OPENING_BUFFER: int = 120;
const SOURCE_TIMEOUT: int = 2400; // setInterrupt(0,1600,2400,"BossCard1") line 57

// ---- boss random movement: source moveRand(60,4,0.4) line 76 -------------------------
// moveLimit(0,128,280,64): x in [-140,140], y in [96,160]; direction inner region
// x +/-70 (width/4), y 112..144 (height/4). Shared slots: int0 next step count,
// fx0/fx1 logical unit direction. Source I0=2 (line 61) is never read in this
// closure, so it is not stored here.
sub move_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.4fx * ((60 - k) as fx) / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // native +/-pi/2 guard, eps 0.05 rad in BAM (nearest boundaries)
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    move_arm_next_step();
}

// ---- main ring: Boss1_at lines 83-122 ----------------------------------------------
// etAim(0,3) fixed-direction ring, base pi/2, 24 ways x 1 layer, etDist 16 (line 118).
// Line 119 overwrites the line-90 speed with 0 before etOn, so the ring spawns at rest
// and the bullet EX accelerates it. ANIM birth stage is omitted; its 4*velocity shift
// is zero at speed 0.
// EX chain: WAIT 10 (line 94) -> ANGLE_ACCEL 50f r=0.035 s=%F0 (line 95) -> SHOOT.
// %F0 alternates +2deg/-2deg per wave (lines 60,70,73).
xformdef PARENT(omega: angle) {
    wait(10);
    set_accel(0.035fx);
    set_ang_vel(omega);
    wait(50);
    set_life(1);
}

sub fire_wave(color: int, omega: angle) {
    sh_reset(0);
    sh_sprite(0, TH14_BIG_BALL, 1);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, 24, 1);
    sh_angle(0, 90deg, 0deg);
    sh_speed(0, 0fx, 0fx);
    sh_dist(0, 16fx);
    sh_xform(0, PARENT(omega));
    if color == 1 { sh_task(0, split_c1); }
    else if color == 2 { sh_task(0, split_c2); }
    else { sh_task(0, split_c3); }
    sh_fire(0);
}

// SHOOT mode 8 (lines 96-113): ways 1/3/5/7 and amplitude 5/5/10/15 deg by difficulty;
// each child samples angle then speed. m=-999 keeps the parent speed, n=1.5 is the
// random speed amplitude; r=-999 keeps the parent angle. Children copy the parent EX
// from index 10: ANIM a=1 (birth stage omitted, 4*velocity shift kept), PLAYSOUND and
// BRIGHT omitted. SHOOT_DATA sprite type5, color $A (2/3/1), delete parent (c=1).
sub parent_split(color: int) {
    wait(59);  // bullet task first runs one frame after birth; SHOOT at parent age 60
    var rank: int = global(GVAR_RANK);
    var ways: int = 1;
    var delta: int = 910;   // 5 deg (0.087266 rad)
    if rank == 1 { ways = 3; }
    if rank >= 2 { ways = 5; delta = 1820; }  // 10 deg (0.174533 rad)
    if rank >= 3 { ways = 7; delta = 2731; }  // 15 deg (0.261799 rad)
    var base_a: angle = $self_angle;
    var base_s: fx = $self_speed;
    for i in 0..ways {
        var ra: int = rand(65536);
        var su: fx = (ra - 32768) as fx / 32768;
        var off: int = ((delta as fx) * su) as int;
        var a: angle = base_a + (off as angle);
        var rv: int = rand(65536);
        var u: fx = (rv - 32768) as fx / 65536 + 0.5fx;
        var sp: fx = base_s + 1.5fx * u;
        var bx: fx = $self_x - 4fx * sp * cos(a);
        var by: fx = $self_y - 4fx * sp * sin(a);
        _ = fire(TH14_BALL2, color, bx, by, sp, a, none, none);
    }
}

async sub split_c1() { parent_split(1); }
async sub split_c2() { parent_split(2); }
async sub split_c3() { parent_split(3); }

// ---- Boss1 body lines 63-79 --------------------------------------------------------
// anmPlay/anmSelect/playSound/fog/stars/lifeMarker are presentation/UI and omitted.
// Schedule keeps source waits 60/30/30/80/70 (270-frame cycle); t is the source
// interrupt clock started at timerReset (line 56), capped at the 2400 timeout.
async sub source_enemy() {
    set_invuln(65535);
    set_hitbox(24fx);   // setHitbox(48,48) line 24, circle radius 48/2
    set_hurtbox(24fx);  // setHurtbox(48,48) line 23
    var t: int = 0;
    while t < SOURCE_TIMEOUT {
        wait(60); t = t + 60;
        if t >= SOURCE_TIMEOUT { break; }
        fire_wave(2, 2deg);        // Boss1_at(2), %F0 = +0.034907
        wait(30); t = t + 30;
        if t >= SOURCE_TIMEOUT { break; }
        fire_wave(3, -2deg);       // %F0 *= -1; Boss1_at(3)
        wait(30); t = t + 30;
        if t >= SOURCE_TIMEOUT { break; }
        fire_wave(1, 2deg);        // %F0 *= -1; Boss1_at(1)
        wait(80); t = t + 80;
        if t >= SOURCE_TIMEOUT { break; }
        move_rand();               // moveRand(60,4,0.4)
        for i in 0..60 {
            if t >= SOURCE_TIMEOUT { break; }
            wait(1);
            move_arm_next_step();
            t = t + 1;
        }
        for j in 0..10 {
            if t >= SOURCE_TIMEOUT { break; }
            wait(1);
            t = t + 1;
        }
    }
    // Native boundary (BossCard1 start, line 334) zeroes velocity; the next attack is
    // not started by this card.
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 11600, 0, 0, 0, source_enemy);  // lifeSet(11600) line 26
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
